head.b:skin:
/* ===== RESET & BASE STYLES ===== */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Be Vietnam Pro', -apple-system, sans-serif;
  background: radial-gradient(circle at 50% 0, #291e14, #0d0906);
  color: #e8dcc6;
  line-height: 1.6;
  min-height: 100vh;
}
a { color: #e5b36a; text-decoration: none; transition: all 0.2s ease; }
a:hover { color: #f1c40f; }

/* ===== NAVBAR ===== */
.kybien-navbar {
  background: linear-gradient(135deg, #8b0000, #4a0000);
  color: #ffffff;
  padding: 14px 20px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5);
  position: relative;
  z-index: 10;
  border-bottom: 2px solid #f1c40f;
}
.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}
.brand-logo {
  font-size: 1.6rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Noto Serif TC', serif;
}
.brand-logo span { color: #f1c40f; }

.logo-general-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #c62828;
  color: #ffffff;
  border: 2px solid #f1c40f;
  font-family: 'Noto Serif TC', serif;
  font-weight: 900;
  font-size: 1.15rem;
  box-shadow: 0 0 10px rgba(241,196,15,0.4);
}

.nav-links { display: flex; gap: 20px; list-style: none; align-items: center; }
.nav-links a { color: #ffffff; font-weight: 600; font-size: 0.95rem; }
.nav-links a:hover { color: #f1c40f; }

/* KHUNG ĐĂNG NHẬP HEADER */
.kybien-nav-auth {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.kybien-nav-auth input {
  background: #1e130a;
  border: 1px solid #5a3d22;
  color: #fff;
  padding: 6px 9px;
  border-radius: 6px;
  font-size: 0.8rem;
  outline: none;
  transition: border-color 0.2s;
}
.kybien-nav-auth input:focus {
  border-color: #f1c40f;
}
.kybien-nav-auth button {
  cursor: pointer;
  font-family: inherit;
}

/* ===== HERO SECTION (TRANG CHỦ) ===== */
.hero-section {
  background: linear-gradient(135deg, #33251a, #1a1009);
  border: 2px solid #5a3d22;
  border-radius: 16px;
  padding: 35px 25px;
  text-align: center;
  margin-bottom: 30px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  position: relative;
}
.hero-badge {
  display: inline-block;
  background: #8b0000;
  color: #f1c40f;
  font-size: 0.82rem;
  font-weight: 700;
  padding: 4px 14px;
  border-radius: 20px;
  border: 1px solid #a83a1f;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.hero-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 2.2rem;
  color: #f1c40f;
  margin-bottom: 10px;
  text-shadow: 0 2px 10px rgba(0,0,0,0.6);
}
.hero-subtitle {
  font-size: 1.05rem;
  color: #e8dcc6;
  max-width: 750px;
  margin: 0 auto 25px auto;
  line-height: 1.6;
}
.hero-actions {
  display: flex;
  justify-content: center;
  gap: 15px;
  flex-wrap: wrap;
}
.btn-hero-primary {
  background: linear-gradient(135deg, #8b0000, #500000);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 1rem;
  padding: 12px 26px;
  border-radius: 10px;
  border: 1px solid #f1c40f;
  box-shadow: 0 4px 15px rgba(241,196,15,0.3);
  transition: transform 0.2s ease;
}
.btn-hero-primary:hover {
  transform: translateY(-2px);
  background: linear-gradient(135deg, #a83a1f, #8b0000);
}
.btn-hero-secondary {
  background: linear-gradient(135deg, #4a3320, #291e14);
  color: #f1c40f !important;
  font-weight: 700;
  font-size: 1rem;
  padding: 12px 26px;
  border-radius: 10px;
  border: 1px solid #5a3d22;
  transition: transform 0.2s ease;
}
.btn-hero-secondary:hover {
  transform: translateY(-2px);
  border-color: #f1c40f;
  color: #fff !important;
}

/* ===== 4 GAME VARIANT CARDS (TRANG CHỦ) ===== */
.variant-cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 18px;
  margin-bottom: 35px;
}
.variant-card {
  background: linear-gradient(145deg, #271a10, #140b05);
  border: 1px solid #5a3d22;
  border-radius: 12px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: all 0.25s ease;
  box-shadow: 0 4px 14px rgba(0,0,0,0.3);
}
.variant-card:hover {
  transform: translateY(-4px);
  border-color: #f1c40f;
  box-shadow: 0 8px 20px rgba(241,196,15,0.25);
}
.variant-icon {
  font-size: 2.2rem;
  margin-bottom: 10px;
}
.variant-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 1.25rem;
  color: #f1c40f;
  margin-bottom: 8px;
}
.variant-desc {
  font-size: 0.88rem;
  color: #a8947d;
  line-height: 1.5;
  margin-bottom: 16px;
}
.btn-play-variant {
  background: linear-gradient(135deg, #8b0000, #5a0000);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 0.85rem;
  padding: 9px 14px;
  border-radius: 6px;
  text-align: center;
  border: 1px solid #a83a1f;
}
.btn-play-variant:hover {
  background: linear-gradient(135deg, #a83a1f, #8b0000);
  color: #f1c40f !important;
}

/* ===== THANH LỌC DANH MỤC (LABEL FILTER BAR) ===== */
.label-filter-bar {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 25px;
  background: rgba(34, 21, 12, 0.6);
  padding: 12px 16px;
  border-radius: 10px;
  border: 1px solid #5a3d22;
}
.filter-btn {
  background: #33251a;
  color: #e8dcc6;
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  border: 1px solid #5a3d22;
  transition: all 0.2s ease;
}
.filter-btn:hover, .filter-btn.active {
  background: #8b0000;
  color: #f1c40f;
  border-color: #f1c40f;
}

/* ===== MAIN LAYOUT ===== */
.main-wrapper {
  max-width: 1200px;
  margin: 20px auto 40px auto;
  padding: 0 15px;
}

.content-area {
  width: 100%;
}

/* SECTION HEADER TITLE */
.section-title-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid #5a3d22;
  padding-bottom: 10px;
  margin-bottom: 25px;
}
.section-title-bar h2 {
  font-family: 'Noto Serif TC', serif;
  font-size: 1.4rem;
  color: #f1c40f;
  letter-spacing: 1px;
}

/* GRID CÁC THẺ BÀI VIẾT BÌNH VĂN SA TRƯỜNG */
.post-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(330px, 100%), 1fr));
  gap: 22px;
}

.post-card {
  background: linear-gradient(145deg, #33251a, #20140b);
  border: 1px solid #5a3d22;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 6px 18px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.25s ease, border-color 0.25s ease;
}
.post-card:hover {
  transform: translateY(-4px);
  border-color: #f1c40f;
  box-shadow: 0 8px 25px rgba(241,196,15,0.2);
}
.post-card-tag {
  display: inline-block;
  background: #8b0000;
  color: #f1c40f;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 4px;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.post-card-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: #f1c40f;
  margin-bottom: 12px;
  line-height: 1.4;
}
.post-card-title a { color: #f1c40f; }
.post-card-title a:hover { color: #fff; }

.post-card-snippet {
  font-size: 0.9rem;
  color: #a8947d;
  line-height: 1.6;
  margin-bottom: 18px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.btn-read-post {
  background: linear-gradient(135deg, #8b0000, #600000);
  color: #ffffff !important;
  font-weight: 700;
  font-size: 0.88rem;
  padding: 10px 18px;
  border-radius: 8px;
  text-align: center;
  display: block;
  border: 1px solid #a83a1f;
  box-shadow: 0 3px 10px rgba(139,0,0,0.4);
}
.btn-read-post:hover {
  background: linear-gradient(135deg, #a83a1f, #8b0000);
  color: #f1c40f !important;
  border-color: #f1c40f;
}

/* CHI TIẾT BÀI VIẾT & TRANG TĨNH SẢNH CỜ (STATIC / ITEM VIEW) */
.single-page-view {
  background: transparent;
  width: 100%;
}
.single-post-title {
  font-family: 'Noto Serif TC', serif;
  font-size: 2rem;
  font-weight: 700;
  color: #f1c40f;
  margin-bottom: 20px;
  text-align: center;
  line-height: 1.3;
}

/* STYLING BÌNH LUẬN SA TRƯỜNG */
.comments-section {
  margin-top: 45px;
  padding-top: 30px;
  border-top: 2px solid #5a3d22;
  background: linear-gradient(145deg, #22150c, #140b05);
  padding: 24px;
  border-radius: 12px;
  border: 1px solid #5a3d22;
}
.comments-title {
  font-family: 'Noto Serif TC', serif;
  color: #f1c40f;
  font-size: 1.4rem;
  margin-bottom: 20px;
}

/* STYLING PHÂN TRANG (PAGINATION) */
.blog-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 35px;
  padding-top: 20px;
  border-top: 1px solid #5a3d22;
}
.blog-pager-newer-link, .blog-pager-older-link, .home-link {
  background: linear-gradient(135deg, #4a3320, #291e14);
  color: #f1c40f !important;
  border: 1px solid #5a3d22;
  padding: 10px 18px;
  border-radius: 8px;
  font-weight: bold;
  font-size: 0.9rem;
  transition: all 0.2s ease;
}
.blog-pager-newer-link:hover, .blog-pager-older-link:hover, .home-link:hover {
  background: linear-gradient(135deg, #8b0000, #4a0000);
  color: #fff !important;
  border-color: #f1c40f;
}

/* FOOTER CHUYÊN NGHIỆP */
footer.kybien-footer {
  text-align: center;
  padding: 25px 20px;
  color: #a8947d;
  font-size: 0.9rem;
  border-top: 1px solid #33251a;
  margin-top: 50px;
  background: #120b06;
}

/* ===== RESPONSIVE MOBILE CHO BÀI VIẾT BLOG & BÀN CỜ (1 CỘT, KHÔNG CỐ ĐỊNH BÀN CỜ) ===== */
.kybien-post-layout {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  align-items: flex-start;
}
.sticky-board-col {
  flex: 1 1 480px;
  max-width: 520px;
  order: 1;
  position: sticky;
  top: 20px;
  box-sizing: border-box;
}
.scrollable-story-col {
  flex: 1 1 420px;
  order: 2;
  box-sizing: border-box;
}

/* Class ẩn thị giác nhưng screen reader vẫn đọc (dùng cho <label> trong form) */
.kybien-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Ô tìm kiếm ở header — theo kiểu dáng theme */
.kybien-header-search {
  display: flex;
  align-items: center;
  gap: 6px;
}
.kybien-header-search input[type='search'] {
  background: #22150c;
  border: 1px solid #5a3d22;
  border-radius: 6px;
  color: #e8dcc6;
  padding: 6px 10px;
  font-size: 0.82rem;
  width: 150px;
  font-family: inherit;
}
.kybien-header-search input[type='search']::placeholder {
  color: #a8947d;
}
.kybien-header-search button {
  background: linear-gradient(135deg, #a83a1f, #8b0000);
  color: #fff;
  border: 1px solid #f1c40f;
  padding: 6px 10px;
  border-radius: 6px;
  font-weight: bold;
  font-size: 0.82rem;
  cursor: pointer;
}

@media (max-width: 900px) {
  .nav-container {
    flex-direction: column;
    gap: 10px;
  }
  .nav-links {
    flex-wrap: wrap;
    justify-content: center;
    gap: 12px;
  }
  .main-wrapper {
    padding: 0 10px;
    margin: 15px auto 30px auto;
  }
  .single-post-title {
    font-size: 1.45rem;
    margin-bottom: 15px;
    line-height: 1.35;
  }
  /* 1 CỘT VÀ KHÔNG CỐ ĐỊNH BÀN CỜ TRÊN MOBILE */
  .kybien-post-layout {
    display: flex !important;
    flex-direction: column !important;
    gap: 18px !important;
  }
  .sticky-board-col {
    position: static !important;
    top: auto !important;
    width: 100% !important;
    max-width: 100% !important;
    flex: 1 1 auto !important;
    order: 1 !important;
    padding: 12px 8px !important;
    margin: 0 auto 10px auto !important;
    box-sizing: border-box !important;
  }
  .scrollable-story-col {
    width: 100% !important;
    max-width: 100% !important;
    flex: 1 1 auto !important;
    order: 2 !important;
    padding: 18px 14px !important;
    margin: 0 auto !important;
    box-sizing: border-box !important;
  }
  #chess-board-canvas {
    width: 100% !important;
    max-width: 100% !important;
    height: auto !important;
  }
  #kybien-replay-canvas {
    width: 100% !important;
    max-width: 440px !important;
    height: auto !important;
  }
  .sa-truong-article {
    font-size: 1.02rem !important;
    line-height: 1.8 !important;
  }
  .sa-truong-article .content {
    text-align: left !important;
  }
  .kybien-variant-header-badge {
    gap: 6px !important;
  }
  .kybien-variant-header-badge span {
    font-size: 0.8rem !important;
    padding: 5px 10px !important;
  }
  .kybien-post-summary-text {
    font-size: 0.95rem !important;
    padding: 10px 14px !important;
  }
  .viewer-controls {
    flex-wrap: wrap !important;
    gap: 6px !important;
  }
  .viewer-controls button {
    padding: 7px 12px !important;
    font-size: 0.82rem !important;
  }
}
@media (max-width: 480px) {
  .hero-title {
    font-size: 1.6rem;
    line-height: 1.3;
  }
  .hero-subtitle {
    font-size: 0.95rem;
  }
  .kybien-header-search {
    width: 100%;
  }
  .kybien-header-search input[type='search'] {
    flex: 1;
    width: auto;
  }
}

b:if.script:
//
                    (function(){
                      var currentCleanUrl = window.location.href.split('?')[0].split('#')[0];
                      var container = document.getElementById('kybien-related-posts-container');
                      if(!container) return;

                      // Escape HTML: tiêu đề/URL lấy từ Blogger Feed là dữ liệu động (tiêu đề bài do người đăng đặt, có thể chứa ký tự đặc biệt). Nối thẳng vào innerHTML sẽ phá vỡ HTML hoặc chèn được script (XSS) nên phải escape trước khi chèn.
                      function escHtml(s){
                        return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
                      }

                      // 1. Đọc danh sách nhãn của bài viết hiện tại từ DOM
                      var tagEls = document.querySelectorAll('#kybien-post-current-labels .rel-tag');
                      var currentTags = [];
                      for(var t = 0; t < tagEls.length; t++){
                        var txt = (tagEls[t].textContent || '').trim();
                        if(txt) currentTags.push(txt);
                      }

                      // 2. Xác định các nhóm nhãn của bài viết hiện tại
                      var groups = [];
                      var hasVariant = false;
                      var hasTranHay = false;

                      for(var i = 0; i < currentTags.length; i++){
                        var tag = currentTags[i];
                        // Nhóm Thể loại cờ
                        if((tag === 'co-bi-phap' || tag === 'Dai chien ky bien' || tag === 'Cờ Bí Pháp') && !hasVariant){
                          groups.push({
                            name: '✨ Cờ Bí Pháp',
                            match: function(itemCats){
                              return itemCats.indexOf('co-bi-phap') !== -1 || itemCats.indexOf('Dai chien ky bien') !== -1 || itemCats.indexOf('Cờ Bí Pháp') !== -1;
                            }
                          });
                          hasVariant = true;
                        } else if((tag === 'co-up' || tag === 'Cờ Úp') && !hasVariant){
                          groups.push({
                            name: '🎴 Cờ Úp',
                            match: function(itemCats){
                              return itemCats.indexOf('co-up') !== -1 || itemCats.indexOf('Cờ Úp') !== -1;
                            }
                          });
                          hasVariant = true;
                        } else if((tag === 'co-up-gian-diep' || tag === 'Cờ Gián Điệp') && !hasVariant){
                          groups.push({
                            name: '🕵️ Cờ Gián Điệp',
                            match: function(itemCats){
                              return itemCats.indexOf('co-up-gian-diep') !== -1 || itemCats.indexOf('Cờ Gián Điệp') !== -1;
                            }
                          });
                          hasVariant = true;
                        } else if((tag === 'co-truyen-thong' || tag === 'Cờ Truyền Thống') && !hasVariant){
                          groups.push({
                            name: '🏯 Cờ Truyền Thống',
                            match: function(itemCats){
                              return itemCats.indexOf('co-truyen-thong') !== -1 || itemCats.indexOf('Cờ Truyền Thống') !== -1;
                            }
                          });
                          hasVariant = true;
                        }
                        // Nhóm Trận Hay
                        else if((tag.indexOf('tran-') === 0 || tag === 'Trận Hay') && !hasTranHay){
                          groups.push({
                            name: '⚔️ Tuyển Tập Trận Hay',
                            match: function(itemCats){
                              for(var c = 0; c < itemCats.length; c++){
                                if(itemCats[c].indexOf('tran-') === 0 || itemCats[c] === 'Trận Hay') return true;
                              }
                              return false;
                            }
                          });
                          hasTranHay = true;
                        }
                      }

                      // Fallback nếu bài viết không thuộc nhóm nào trên
                      if(!groups.length){
                        groups.push({
                          name: '📜 Bình Văn Sa Trường',
                          match: function(){ return true; }
                        });
                      }

                      // 3. Tải danh sách bài viết từ Blogger Feed
                      fetch('/feeds/posts/summary?alt=json&max-results=30')
                        .then(function(r){ return r.json(); })
                        .then(function(data){
                          if(!data || !data.feed || !data.feed.entry || !data.feed.entry.length){
                            container.innerHTML = '<div style="color: #a8947d; font-size: 0.85rem; font-style: italic;">Chưa có ván cờ tương quan khác.</div>';
                            return;
                          }

                          var entries = data.feed.entry;
                          var pickedUrls = {};
                          var totalLimit = 5;
                          var quotaPerGroup = Math.ceil(totalLimit / groups.length);
                          var groupResults = [];

                          for(var g = 0; g < groups.length; g++){
                            var grp = groups[g];
                            var grpItems = [];

                            for(var e = 0; e < entries.length; e++){
                              var item = entries[e];
                              var pUrl = '';
                              if(item.link){
                                for(var k = 0; k < item.link.length; k++){
                                  if(item.link[k].rel === 'alternate'){ pUrl = item.link[k].href; break; }
                                }
                              }
                              if(!pUrl || pUrl.split('?')[0].split('#')[0] === currentCleanUrl) continue;
                              if(pickedUrls[pUrl]) continue;

                              var itemCats = [];
                              if(item.category){
                                for(var c = 0; c < item.category.length; c++){
                                  if(item.category[c].term) itemCats.push(item.category[c].term);
                                }
                              }

                              if(grp.match(itemCats)){
                                var pTitle = item.title ? item.title.$t : 'Ván Cờ Sa Trường';
                                grpItems.push({ url: pUrl, title: pTitle });
                                pickedUrls[pUrl] = true;
                                if(grpItems.length >= quotaPerGroup || Object.keys(pickedUrls).length >= totalLimit){
                                  break;
                                }
                              }
                            }

                            if(grpItems.length){
                              groupResults.push({ name: grp.name, items: grpItems });
                            }
                          }

                          // Bù thêm bài nếu tổng số bài dưới 5
                          var currentCount = Object.keys(pickedUrls).length;
                          if(currentCount < totalLimit){
                            var extraItems = [];
                            for(var e2 = 0; e2 < entries.length && currentCount < totalLimit; e2++){
                              var item2 = entries[e2];
                              var pUrl2 = '';
                              if(item2.link){
                                for(var k2 = 0; k2 < item2.link.length; k2++){
                                  if(item2.link[k2].rel === 'alternate'){ pUrl2 = item2.link[k2].href; break; }
                                }
                              }
                              if(!pUrl2 || pUrl2.split('?')[0].split('#')[0] === currentCleanUrl) continue;
                              if(pickedUrls[pUrl2]) continue;

                              var pTitle2 = item2.title ? item2.title.$t : 'Ván Cờ Sa Trường';
                              extraItems.push({ url: pUrl2, title: pTitle2 });
                              pickedUrls[pUrl2] = true;
                              currentCount++;
                            }
                            if(extraItems.length){
                              groupResults.push({ name: '📜 Tuyển Tập Kỳ Đàm Khác', items: extraItems });
                            }
                          }

                          if(!groupResults.length){
                            container.innerHTML = '<div style="color: #a8947d; font-size: 0.85rem; font-style: italic;">Chưa có ván cờ tương quan khác.</div>';
                            return;
                          }

                          // Render giao diện theo từng nhãn chủ đề, mỗi bài đúng 1 dòng title
                          var html = '';
                          for(var gr = 0; gr < groupResults.length; gr++){
                            var resGrp = groupResults[gr];
                            html += '<div style="margin-bottom: 14px;">' +
                              '<div style="font-size: 0.88rem; font-weight: bold; color: #f1c40f; margin-bottom: 8px; display: flex; align-items: center; gap: 6px;">' +
                                '<span>🏷️</span>' +
                                '<span>Chủ đề: <b>' + escHtml(resGrp.name) + '</b></span>' +
                              '</div>' +
                              '<ul style="list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 6px;">';

                            for(var it = 0; it < resGrp.items.length; it++){
                              var postObj = resGrp.items[it];
                              html += '<li style="display: flex; align-items: center; gap: 8px; font-size: 0.92rem; padding: 7px 12px; background: rgba(34,21,12,0.55); border: 1px solid #4a301a; border-radius: 6px;">' +
                                '<span style="color: #e57373; font-size: 0.72rem;">▶</span>' +
                                '<a href="' + escHtml(postObj.url) + '" style="color: #e8dcc6; text-decoration: none; font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1;" title="' + escHtml(postObj.title) + '">' +
                                  escHtml(postObj.title) +
                                '</a>' +
                              '</li>';
                            }

                            html += '</ul></div>';
                          }

                          container.innerHTML = html;
                        })
                        .catch(function(err){
                          if(container) container.innerHTML = '<div style="color: #a8947d; font-size: 0.85rem;"><a href="/search/label/phan-tich-co" style="color:#f1c40f;">Xem thêm toàn bộ ván đấu tại Thư Viện Bình Văn ➔</a></div>';
                        });
                    })();
                    //

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

footer.script:
//
    (function(){
      var dot=document.getElementById('online-status-dot');
      var el=document.getElementById('online-stats-text');
      // Chấm trạng thái: xám = chưa rõ/đang tải, xanh = máy chủ đang chạy, đỏ = không kết nối được.
      function setDot(color, glow){
        if(!dot) return;
        dot.style.background=color;
        dot.style.boxShadow=glow ? ('0 0 10px ' + color) : 'none';
      }
      function setOffline(){
        setDot('#e74c3c', true);
        if(el) el.innerHTML='Máy chủ tạm nghỉ — Không kết nối được máy chủ, thử lại sau.';
      }
      function renderStats(s){
        if(!s) return;
        setDot('#2ecc71', true);
        if(el){
          var t=+s.total||0,m=+s.members||0,g=+s.guests||0;
          el.innerHTML='Tề tựu: <b>'+t+'</b> vị (<b>'+m+'</b> Kỳ thủ • <b>'+g+'</b> Lữ khách)';
        }
      }
      var controller=(typeof AbortController !== 'undefined') ? new AbortController() : null;
      var timer=null;
      if(controller) timer=setTimeout(function(){ controller.abort(); }, 8000);
      var opts=controller ? { signal: controller.signal } : {};
      fetch('https://kybien-backend.onrender.com/api/stats/online', opts)
        .then(function(r){ if(!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
        .then(function(d){ if(timer) clearTimeout(timer); if(d && d.data) renderStats(d.data); else setOffline(); })
        .catch(function(){ if(timer) clearTimeout(timer); setOffline(); });
    })();
    //
